class TokenBucket {
  constructor({ capacity, refillPerSecond, now }) {
    if (
      typeof capacity !== 'number' ||
      !Number.isFinite(capacity) ||
      capacity <= 0
    ) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFn = typeof now === 'function' ? now : Date.now;
    this.maxTime = this.nowFn();
    this.tokens = capacity;
  }

  _refill(nowMs) {
    const delta = nowMs - this.maxTime;
    if (delta <= 0) return;
    this.maxTime = nowMs;
    const refilled = (delta / 1000) * this.refillPerSecond;
    this.tokens = Math.min(this.capacity, this.tokens + refilled);
  }

  tryTake(n = 1) {
    if (
      typeof n !== 'number' ||
      !Number.isFinite(n) ||
      n <= 0
    ) {
      throw new RangeError('n must be a positive finite number');
    }
    this._refill(this.nowFn());
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill(this.nowFn());
    return this.tokens;
  }

  msUntil(n = 1) {
    if (
      typeof n !== 'number' ||
      !Number.isFinite(n) ||
      n <= 0
    ) {
      throw new RangeError('n must be a positive finite number');
    }
    if (n > this.capacity) {
      return Infinity;
    }
    if (this.refillPerSecond === 0) {
      const cur = this.available();
      if (cur >= n) return 0;
      return Infinity;
    }
    const cur = this.available();
    if (cur >= n) return 0;
    const deficit = n - cur;
    const secondsNeeded = deficit / this.refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

