import subprocess
result = subprocess.run(
    ['node', '-e', r'''
const { TokenBucket } = require('./kova.js');

let t = 1000;
const fakeNow = () => t;
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: fakeNow });

// Test 1: Başlangıç dolu
console.assert(bucket.available() === 10, 'available başlangıç: ' + bucket.available());

// Test 2: tryTake
console.assert(bucket.tryTake(3) === true, 'tryTake(3)');
console.assert(bucket.available() === 7, 'available after take 3: ' + bucket.available());

// Test 3: yetmezse false
console.assert(bucket.tryTake(20) === false, 'tryTake(20) false');
console.assert(bucket.available() === 7, 'available after failed take: ' + bucket.available());

// Test 4: refill
t = 2000; // 1 saniye geçti
console.assert(Math.abs(bucket.available() - 12) < 0.001, 'refill: ' + bucket.available());

// Test 5: capacity sınırı
t = 10000;
console.assert(Math.abs(bucket.available() - 10) < 0.001, 'capacity cap: ' + bucket.available());

// Test 6: msUntil
let b2 = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: () => 1000 });
console.assert(b2.msUntil(1) === 0, 'msUntil zaten yeterli: ' + b2.msUntil(1));
let b3 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => 1000 });
// available = 10, msUntil(10) = 0
console.assert(b3.msUntil(10) === 0, 'msUntil(10) zaten: ' + b3.msUntil(10));
let b4 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => 1000 });
b4.tryTake(10); // 0 kaldı
console.assert(b4.msUntil(5) === 5000, 'msUntil 5 jeton 1/s: ' + b4.msUntil(5));

// Test 7: n > capacity -> Infinity
let b5 = new TokenBucket({ capacity: 10, refillPerSecond: 100, now: () => 1000 });
console.assert(b5.msUntil(11) === Infinity, 'msUntil n>cap: ' + b5.msUntil(11));

// Test 8: refillPerSecond = 0
let b6 = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 1000 });
console.assert(b6.msUntil(6) === Infinity, 'msUntil n>cap refill0: ' + b6.msUntil(6));
console.assert(b6.msUntil(1) === 0, 'msUntil zaten var refill0: ' + b6.msUntil(1));
b6.tryTake(5);
console.assert(b6.msUntil(1) === Infinity, 'msUntil 0 refill dolmuyor: ' + b6.msUntil(1));

// Test 9: saat geri giderse maxTime artmaz
let t2 = 1000;
let b7 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => t2 });
t2 = 2000; // 1 saniye, 1 jeton dolar -> 11 -> 10 (cap)
console.assert(Math.abs(b7.available() - 10) < 0.001, 'refill cap: ' + b7.available());
t2 = 1000; // geri giderse hiçbir şey olmaz
b7.tokens = 5; // manuel boz
t2 = 500;
let avail = b7.available();
console.assert(avail === 5, 'saat geri: ' + avail);

// Test 10: invalid capacity
try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); console.error('FAIL: negative cap'); process.exit(1); } catch(e) { if (!(e instanceof RangeError)) { console.error('FAIL: not RangeError'); process.exit(1); } }
try { new TokenBucket({ capacity: Infinity, refillPerSecond: 1 }); console.error('FAIL: inf cap'); process.exit(1); } catch(e) { if (!(e instanceof RangeError)) { console.error('FAIL: not RangeError'); process.exit(1); } }

// Test 11: invalid n
let b8 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => 1000 });
try { b8.tryTake(-1); console.error('FAIL: negative n'); process.exit(1); } catch(e) { if (!(e instanceof RangeError)) { console.error('FAIL: not RangeError'); process.exit(1); } }
try { b8.msUntil(0); console.error('FAIL: zero n'); process.exit(1); } catch(e) { if (!(e instanceof RangeError)) { console.error('FAIL: not RangeError'); process.exit(1); } }

console.log('Tüm testler geçti!');
''', 'exit'],
    capture_output=True, text=True
)
print('stdout:', result.stdout)
print('stderr:', result.stderr)
print('exit code:', result.returncode)

