try { new TokenBucket({ capacity: Infinity, refillPerSecond: 1 }); console.log('FAIL inf'); }
catch(e) { console.log('OK inf cap ->', e.name); }

try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); console.log('FAIL zero'); }
catch(e) { console.log('OK zero cap ->', e.name); }

