try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); console.log('FAIL neg refill'); }
catch(e) { console.log('OK negative refill ->', e.name); }

// refillPerSecond = 0
let b = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 1000 });
b.tryTake(5);
console.log('msUntil(1) refill0:', b.msUntil(1)); // Infinity

// saat geri
let t = 2000;
let b2 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => t });
t = 3000;
console.log('refill 1s:', b2.available()); // ~11 capped to 10
t = 1000; // geri
let avail = b2.available();
console.log('saat geri avail:', avail); // aynı kalmalı

// geçersiz n
let b3 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => 1000 });
try { b3.tryTake(NaN); } catch(e) { console.log('OK NaN n ->', e.name); }
try { b3.tryTake(Infinity); } catch(e) { console.log('OK inf n ->', e.name); }
try { b3.msUntil(0); } catch(e) { console.log('OK zero n ->', e.name); }
